async function run(){
  const page = figma.getNodeById('3:2');
  await figma.setCurrentPageAsync(page);
  // remove old test frames to keep clean
  for (const child of [...page.children]) {
    if (child.name.indexOf('__') === 0 || child.name.indexOf('simpletest')===0 || child.name.indexOf('DEFAULTFONT')===0 || child.name.indexOf('OK_')===0) { child.remove(); }
  }
  // create instances of key media symbols
  const specs = [
    ['1:32','StatusBar','SB'],
    ['1:42','HomeInd','HI'],
    ['1:271','Photo','PH'],
    ['1:212','Cover3am','C3'],
    ['1:240','IconGoogle','IG'],
    ['1:269','LogoMark','LM'],
    ['1:270','LogoWord','LW'],
    ['1:218','CoverGrainy','CG']
  ];
  let y=0;
  for(const s of specs){
    const n=figma.getNodeById(s[0]);
    if(!n){ const f=figma.createFrame(); f.resize(200,60); f.name=s[1]+'_MISSING'; f.x=0; f.y=y; page.appendChild(f); y+=70; continue; }
    try{
      const inst=n.createInstance();
      inst.name=s[1]+'_inst';
      inst.x=0; inst.y=y;
      page.appendChild(inst);
    }catch(e){ const f=figma.createFrame(); f.resize(200,60); f.name=s[1]+'_ERR'; f.x=0; f.y=y; page.appendChild(f); }
    y = y + (s[1]==='StatusBar'?50:(s[1]==='HomeInd'?40:120));
  }
}
