    const t=figma.createText();
    t.fontName={family:'Inter', style:weight||'Regular'};
    t.fontSize=size||14; t.characters=str; t.x=x; t.y=y;
    t.fills=[{type:'SOLID', color:hh(color||C.text)}];
    parent.appendChild(t); return t;
