  rect(btnComp,0,0,340,52,C.brand,26);
  txt(btnComp,0,16,'Button',16,'Bold',bg);
  btnComp.finds = null;
  // set text center via resize
  const btnLabel = btnComp.children.find(c=>c.type==='TEXT');
  btnLabel.resize(340,14); btnLabel.textAlignHorizontal='CENTER'; btnLabel.textAutoResize='WIDTH_AND_HEIGHT';
