  f.fills=[{type:'SOLID',color:{r:0.055,g:0.059,b:0.078}}];
  page.appendChild(f);

  function inst(srcid, parent, width, height, px, py){
    const src = figma.getNodeById(srcid);
    const it = src.createInstance();
    it.resize(width,height); it.x=px; it.y=py;
    parent.appendChild(it); return it;
  }
  function text(parent, str, x, y, size, style, color, align){
    const t = figma.createText();
    try{ t.fontName={family:'Inter', style:style}; }catch(e){}
    t.fontSize=size; t.characters=str;
    t.fills=[{type:'SOLID',color:color}];
    t.x=x; t.y=y;
    if(align){ t.textAlignHorizontal=align; }
    t.resize(t.width, t.height);
    parent.appendChild(t); return t;
  }
  const WHITE={r:0.93,g:0.94,b:0.965};
  const TEAL={r:0,g:0.76,b:0.796};
  const GRAY={r:0.60,g:0.63,b:0.69};

