    f.appendChild(btn);
    inst(p.icon, btn, 24,24, 18,16);
    text(btn, p.label, 214, 20, 15, 'Medium', WHITE, 'CENTER');
    py+=72;
  }

  // Divider "or"
  text(f, "or", 214, py+10, 14, 'Regular', GRAY, 'CENTER');

