async function run(){
  const page = figma.getNodeById('3:2');
  await figma.setCurrentPageAsync(page);
  function findAll(n, name){
    const out=[];
    if(n.children){ for(const c of n.children){ if(c.name===name) out.push(c); out.push(...findAll(c,name)); } }
    return out;
  }
  function setActive(screenId, tabName){
    const sc = figma.getNodeById(screenId);
    const tb = findAll(sc,'Tab Bar')[0];
    if(!tb) return 'no tabbar';
    const tabs = findAll(tb, tabName)[0];
    if(!tabs) return 'no '+tabName;
    const teal={r:0,g:0.76,b:0.795};
    // recolor icon instances
    const icons = tabs.children.filter(c=>c.type==='INSTANCE');
    for(const ic of icons){ ic.children.forEach(function(v){ if(v.fills && v.fills.length && v.fills[0].type==='SOLID'){ v.fills=[{type:'SOLID',color:teal}]; } }); }
    const texts = tabs.children.filter(c=>c.type==='TEXT');
    for(const t of texts){ t.fills=[{type:'SOLID',color:teal}]; }
    return 'active '+tabName;
  }
  const r1=setActive('2045:90','Tab_Home');     // 04 current Home
  const r2=setActive('2045:166','Tab_Explore'); // 05 current Explore
  const r3=setActive('2047:120','Tab_Library'); // 06 current Library
  const r4=setActive('2049:157','Tab_Library'); // 07
  const r5=setActive('2050:208','Tab_Library'); // 08
  const r6=setActive('2051:241','Tab_Library'); // 09
  const done=figma.createFrame(); done.resize(8,8); done.name='TABACTIVE_DONE'; page.appendChild(done);
}
run();
